package com.mendes.scheduling_platform.publicpage;
import com.mendes.scheduling_platform.availability.*; import com.mendes.scheduling_platform.blockedperiod.*; import com.mendes.scheduling_platform.booking.*; import com.mendes.scheduling_platform.exception.*; import com.mendes.scheduling_platform.tenant.*; import com.mendes.scheduling_platform.venue.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/public/{slug}") public class PublicPageController { private final TenantRepository tenants;private final VenueRepository venues;private final AvailabilityRepository availability;private final BookingRepository bookings;private final BlockedPeriodRepository blocked;private final BookingService service;public PublicPageController(TenantRepository t,VenueRepository v,AvailabilityRepository a,BookingRepository b,BlockedPeriodRepository p,BookingService s){tenants=t;venues=v;availability=a;bookings=b;blocked=p;service=s;} private Tenant tenant(String slug){return tenants.findBySlug(slug).filter(t->t.getStatus()==Tenant.TenantStatus.ACTIVE).orElseThrow(()->new NotFoundException("Estabelecimento não encontrado"));}@GetMapping Tenant page(@PathVariable String slug){return tenant(slug);}@GetMapping("/venues") List<Venue> venueList(@PathVariable String slug){return venues.findAllByTenantIdAndActiveTrue(tenant(slug).getId());}@GetMapping("/venues/{venueId}/slots") List<OffsetDateTime> slots(@PathVariable String slug,@PathVariable Long venueId,@RequestParam LocalDate date,@RequestParam(defaultValue="-03:00") ZoneOffset offset){Tenant t=tenant(slug);Venue v=venues.findByIdAndTenantId(venueId,t.getId()).filter(Venue::isActive).orElseThrow(()->new NotFoundException("Espaço não encontrado"));List<OffsetDateTime> out=new ArrayList<>();for(Availability a:availability.findAllByTenantIdAndVenueId(t.getId(),venueId)){if(a.getDayOfWeek()!=date.getDayOfWeek())continue;for(LocalTime time=a.getStartTime();!time.plusMinutes(v.getDurationMinutes()).isAfter(a.getEndTime());time=time.plusMinutes(v.getDurationMinutes())){OffsetDateTime start=OffsetDateTime.of(date,time,offset),end=start.plusMinutes(v.getDurationMinutes());if(start.isAfter(OffsetDateTime.now())&&!bookings.existsConflict(t.getId(),venueId,start,end)&&!blocked.overlaps(t.getId(),venueId,start,end))out.add(start);}}return out;}@PostMapping("/bookings") Booking book(@PathVariable String slug,@RequestBody BookingService.Request request){return service.create(tenant(slug).getId(),request);} }
